const TOOLS = [
  {
    name: 'order_status',
    description: 'Get the current status of an order. Set include_history=true to also return the chronological status history.',
    inputSchema: {
      type: 'object',
      properties: {
        order_id: { type: 'string', description: 'The order identifier.' },
        include_history: { type: 'boolean', description: 'Whether to include chronological status history. Defaults to false.' }
      },
      required: ['order_id'],
      additionalProperties: false
    }
  }
];

function text(content) {
  return { content: [{ type: 'text', text: content }] };
}

function isError(result) {
  return result && result.isError === true;
}

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args = {}) {
  if (name !== 'order_status') {
    return { isError: true, content: [{ type: 'text', text: `Unknown tool: ${name}` }] };
  }

  // Validate that no extra/unknown fields are present.
  const allowed = new Set(['order_id', 'include_history']);
  const extra = Object.keys(args).filter((k) => !allowed.has(k));
  if (extra.length > 0) {
    return { isError: true, content: [{ type: 'text', text: `Invalid fields: ${extra.join(', ')}` }] };
  }

  const { order_id, include_history = false } = args;

  // Validate required field presence and type.
  if (order_id === undefined || order_id === null) {
    return { isError: true, content: [{ type: 'text', text: 'Missing required field: order_id' }] };
  }
  if (typeof order_id !== 'string') {
    return { isError: true, content: [{ type: 'text', text: 'order_id must be a string' }] };
  }
  if (typeof include_history !== 'boolean') {
    return { isError: true, content: [{ type: 'text', text: 'include_history must be a boolean' }] };
  }

  // Reject missing/unknown orders.
  const order = orders[order_id];
  if (!order) {
    return { isError: true, content: [{ type: 'text', text: `Order not found: ${order_id}` }] };
  }

  const lines = [`Order ${order_id}: status=${order.status}`];
  if (include_history) {
    lines.push(`History: ${(order.history || []).join(' -> ')}`);
  }

  return text(lines.join('\n'));
}

